on conflict (id) do update set participant=excluded.participant, mois=excluded.mois, poids=excluded.poids, gras=excluded.gras, muscle=excluded.muscle, os=excluded.os, eau=excluded.eau, visc=excluded.visc, bmr=excluded.bmr, age_meta=excluded.age_meta, seg_m=excluded.seg_m, seg_g=excluded.seg_g, mens=excluded.mens, egym=excluded.egym, perf=excluded.perf, goals_result=excluded.goals_result, pre=excluded.pre, present=excluded.present, extra=excluded.extra;
update reglages set season='{"num":1,"start":"2026-09","end":"2026-11"}'::jsonb where id=1;
select participant, count(*) from pesees group by participant order by participant;